with source_products(name, description, price, cost_price, unit_type, stock_quantity, is_available, image_1_url, image_2_url, category_name) as (
values
  ('طقم أكواب "بوبا" الزجاجي', 'الجمال في التفاصيل! ✨ طقم أكواب "بوبا" الزجاجي وصل ليضيف لمسة شياكة غير عادية لقهوتك اليومية. تصميم مضلع ومقبض لؤلؤي يخطف القلب قبل العين. ❤️☕ #ديكور #أكواب_قهوة #شياكة #قهوة_الصباح #BobaMug #Glassware #HomeDecor #CoffeeLovers #KitchenStyle', 75, 75, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmksi7hbm0jcz01gn7xwq8und_mug_boba.webp', 'https://assets.wuiltstore.com/cmksi7i6j0jd001gncqg96t5d_mug_boba1.webp', 'العروض الحالية'),
  ('فانوس رمضان مضيء بتصميم "فنانيس" زيت  - ديكور رمضاني عصري', '"أضف لمسة من السحر والبهجة إلى منزلك مع فانوس رمضان المودرن المضيء. يتميز هذا الفانوس بتصميم فريد يدمج بين عراقة الفانوس التقليدي وحداثة كرات الثلج، حيث يحتوي بداخله على شخصيات فنانيس المحبوبة محاطة ببريق الجليتر الذي يتحرك مع الإضاءة ليخلق أجواءً رمضانية دافئة. مميزات المنتج: تصميم أنيق: هيكل خارجي بلون برونزي معتق يناسب جميع أنواع الديكور. إضاءة داخلية: توفر توهجاً ناعماً يبرز تفاصيل الشخصيات والجليتر. هدية مثالية: يعتبر خياراً رائعاً كهدية رمضانية للأهل والأصدقاء أو كقطعة ديكور أساسية لغرف المعيشة والمكاتب. جودة عالية: مصنوع من مواد متينة تضمن لك الاستدامة طوال الشهر الكريم."', 160, 160, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmksayjnn0irg01gn71vwbipi_WhatsApp_Image_2026-01-22_at_8.12.49_PM.webp', 'https://assets.wuiltstore.com/cmksaykps0irh01gn7eedgm7i_WhatsApp_Image_2026-01-22_at_8.12.50_PM__1_.webp', 'العروض الحالية'),
  ('تربو معدن مدور  4 دور  مدور', 'تربو معدن مدور 4 دور و 5 دور 😍مربع ومدور بعجل متحرك متعدد الاستخدام يستخدم ك تربو للمطبخ للخضار والفاكهه 🥬 أو في الحمام للشاور والشامبو🧻🧴 أو يستخدم في المكتب وغرف الاطفال لحمل جميع الأشياء في مكان واحد مزود بعجل متين لسهوله الحركه والتنظيف خلفه', 575, 575, 'piece'::public.unit_type, 3, true, 'https://assets.wuiltstore.com/cmj4b2slt03ef01jxgm3k5rxq__D8_AA_D8_B1_D8_A8_D9_883.jpg', 'https://assets.wuiltstore.com/cmj4b2rqs03ee01jx8hva01dn__D8_AA_D8_B1_D8_A8_D9_882.jpg', 'عروض نهاية السنة'),
  ('تربو معدن مدور 5 دور مدور', 'تربو معدن مدور 5 دور 😍 بعجل متحرك متعدد الاستخدام يستخدم ك تربو للمطبخ للخضار والفاكهه 🥬 أو في الحمام للشاور والشامبو🧻🧴 أو يستخدم في المكتب وغرف الاطفال لحمل جميع الأشياء في مكان واحد مزود بعجل متين لسهوله الحركه والتنظيف خلفه', 635, 635, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmj4b4yhv03ep01jx6xc5cd6z__D8_AA_D8_B1_D8_A8_D9_883.jpg', 'https://assets.wuiltstore.com/cmj4b4xmj03eo01jx186q1kmq__D8_AA_D8_B1_D8_A8_D9_882.jpg', 'Perla Space'),
  ('سكرو صاحب صاحبه', '- سكرو (نسخة صاحب صاحبه) - تقدر تلعبها 2 ضد 2 أو بشكل فردي - 3 كروت جديدة - تحتوى على 66 كارت - علبة جديدة بتصميم مميز', 99, 60, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmbqeykx00u5a01lj0uga9y1m_WhatsApp_Image_2025-05-20_at_15.18.35_75f283b5.jpg', 'https://assets.wuiltstore.com/cmbqeylqn0u5b01ljdhf89utj_490495606_9754171471313893_2836460690513763418_n.jpg', 'Card games'),
  ('لانش باج ستانليس', 'شنطة لانش باج 4 قطعه ستانليس مختوم 304', 380, 380, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmj630fwq002x01jxfy6sfzwp__D9_84_D8_A7_D9_86_D8_B4.jpg', 'https://assets.wuiltstore.com/cmk4d99tc07ez01fu71mvfywq_photo_2026-01-06_21-54-29.webp', 'هدايا'),
  ('مج ستانلي الاصلي', 'مشروبك معاك.. حرارته مابتتغيرش! زهقت إن القهوة بتبرد بسرعة؟ أو المية بتسخن في العربية؟ الحل بقى متاح معانا . مج ستانلي الأصلي هو رفيقك المثالي في كل مشوار: سعة كبيرة تكفيك طول اليوم. شاليموه قوي ومقبض مريح جداً في الاستخدام. متاح بكل الألوان اللي في الصورة (الأسود، الأزرق، البينك، الأخضر، والأبيض).', 350, 350, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmjdfjve3064k01irayzo8sv5_WhatsApp_Image_2025-12-16_at_9.25.18_PM__2_.jpeg', 'https://assets.wuiltstore.com/cmjdfjuci064j01ir8exn76kc_597088269_842847858525256_3152281467577983644_n.jpg', 'هدايا'),
  ('مج عسلي بالشاليموه اكليريك', 'مج عسلي ومعايا الشاليموه اكليريك ب 35 جنيه', 30, 30, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmj47q0eq038a01jx1bvc04sj__D9_85_D8_AC1.jpg', null, 'هدايا'),
  ('مج قهوة فلتر', 'مج قهوة بفلتر', 90, 90, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmj61mhlp01nx01jxc9bk66s7__D9_85_D8_AC_D9_86_D8_B3_D9_83_D8_A7_D9_81.jpg', null, 'هدايا'),
  ('مكعبات ليجو لتنمية المهارات', 'ليجو مش 200 قطعة ولا 500 ليجو الـ 1000 قطعة 🤩 ✨ المميز في الليجو عن اى مكعبات تانية فك وتركيب انها مكعبات صغيرة ومعاها قطع تانية مختلفة تكون بيها مدينة كاملة 🤩 📌كيس مكعبات فيه ١٠٠٠ قطعة 📌خامة وجودة عالية👍 📌من مميزاتها تنمي خيال وذكاء الأطفال وقدرتهم علي الابداع 🥳 📌سهلة الفك والتركيب 📌 بتساعد على زيادة التركيز والانتباه وحل المشكلات 👌🏻 📌تحفز الشعور بالانجاز عند الوصول للشكل المطلوب🥇😉 📌مناسبة من عمر ٣ سنوات 📌مناسبة كهدية 🎁', 370, 370, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmj486rfd039d01jx7vga8g7s__D9_84_D9_8A_D8_AC_D9_881.jpg', 'https://assets.wuiltstore.com/cmj486t6b039f01jx9iex92eu__D9_84_D9_8A_D8_AC_D9_882.jpg', 'العاب'),
  ('ولعه', 'ولعه هي لعبة ورقية تعتمد على الحظ والذكاء في نفس الوقت. تعتمد على توزيع الأوراق بين اللاعبين، ثم يتم لعب الأوراق بشكل متتابع حسب قواعد محددة، مع تحديد الهدف النهائي للفوز في اللعبة. يمكن أن يتراوح عدد اللاعبين من 3 إلى 6 لاعبين، مما يسمح للمجموعات الكبيرة بالاستمتاع بها بشكل مشترك. يطلق على لعبة ولعة أيضًا اسم “لعبة الحظ والمهارة”،', 55, 35, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmbqelnm10u4b01ljh8qv99xt_download__2_.jpg', 'https://assets.wuiltstore.com/cmbqelo5w0u4c01ljbba18qeg_images__2_.jpg', 'Card games'),
  ('مضرب حليب وشحن USB كهربائي - خفاقة قهوة ونسكافيه متعددة السرعات مع رؤوس قابلة للتبديل', 'وداعاً للبطاريات! 🔋 احصل على مضرب الحليب القابل للشحن USB الأقوى في فئته. ✅ محرك قوي وسريع. ✅ 2 رأس قابل للتبديل (للخفق والرغوة). ✅ تصميم عصري وسهل التنظيف. اطلبه الآن وتمتع بمذاق القهوة الاحترافي كل يوم! 🛒💨 #عرض_خاص #تسوق_اونلاين #اجهزة_منزلية #مطبخ #تجهيزات_رمضان #SmartGadgets #KitchenTools', 100, 100, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmj62y4k7001b01jx8ex4a7i9__D9_85_D8_B6.jpg', null, 'عروض نهاية السنة'),
  ('اباجورة زيرو كريستال مودرن - أباجورة إضاءة ذهبية دافئة بتصميم حلقة بيضاوية فاخرة', '"أضف لمسة من الفخامة العصرية إلى منزلك مع مصباح الطاولة الكريستالي الفريد. تتميز هذه الأباجورة المودرن بتصميم هندسي على شكل حلقة بيضاوية مغطاة بقطع الكريستال التي تعكس الإضاءة بشكل ساحر، مما يخلق نقوشاً ضوئية جذابة على الجدران. مميزات المنتج: تصميم عصري: قاعدة ذهبية مصقولة تتناسب مع الديكورات الكلاسيكية والحديثة. إضاءة دافئة: مثالي لغرف النوم، غرف المعيشة، أو كقطعة ديكور فاخرة على طاولة المكتب لتوفير أجواء مريحة وهادئة. جودة عالية: مصنوع من مواد متينة وكريستال عالي النقاء لضمان بريق يدوم طويلًا. توفير الطاقة: متوافق مع تقنيات الإضاءة الموفرة للطاقة. اجعل مساحتك تشع بالأناقة والرفاهية مع هذا المصباح الذي يجمع بين الوظيفة والجمال الفني."', 135, 135, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmjddh0xj05tk01ir53as5r6b_photo_2025-12-19_23-06-27.jpg', 'https://assets.wuiltstore.com/cmjddgzvj05tj01ir13l955y0_photo_2025-12-19_23-10-18.jpg', 'عروض نهاية السنة'),
  ('قطاعة خضار يدوية 16 قطعة مستوردة - قطاعة ومبشرة متعددة الوظائف لجميع أنواع الخضروات والفواكه', '"اختصري ساعات التحضير في دقائق مع قطاعة الخضار الاحترافية 16 في 1 . هي ليست مجرد قطاعة، بل هي مساعدك الشخصي في المطبخ الذي يضمن لكِ تقطيعاً متساوياً واحترافياً لكل أنواع السلطات والطبخات بلمسة واحدة. المواصفات والمميزات: تنوع لا حدود له: تأتي مع 16 قطعة وملحق تشمل أسلحة لتقطيع المكعبات، الشرائح، البشر الناعم، والتقطيع المضلع. خامات مستوردة: الأسلحة مصنوعة من الاستانلس ستيل المقاوم للصدأ والحاد جداً لضمان سهولة التقطيع. وعاء تجميع كبير: مزودة بحاوية شفافة لتجميع الخضروات المقطعة مباشرة، مما يحافظ على نظافة مطبخك. أمان تام: مصممة بمقبض مريح وحماية لليد تضمن لكِ التقطيع بأمان دون ملامسة الشفرات. سهولة التنظيف: جميع القطع قابلة للفك والتركيب والعمل في غسالة الأطباق بسهولة. مثالية لرمضان: توفر مجهودك في تقطيع خضروات الشوربة، السلطات، والتزيين في أسرع وقت."', 160, 160, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmjcwp8vz04an01irhwm5eot0_WhatsApp_Image_2025-12-16_at_9.25.22_PM__3_.jpeg', 'https://assets.wuiltstore.com/cmjq5cj5a013801fu9lkq4wwr__D9_82_D8_B7_D8_A7_D8_B91.jpg', 'العروض الحالية'),
  ('طقم بولات زجاج على شكل قلب بحواف ذهبية - أطباق تقديم حلي ومكسرات فاخرة', '"اجعلي كل لحظة تقديم تنبض بالحب مع طقم بولات القلب الزجاجية . صُممت هذه البولات خصيصاً لمن يبحثون عن الأناقة والتميز في تفاصيل سفرتهم، حيث يمتزج نقاء الزجاج مع فخامة اللون الذهبي. المواصفات والمميزات: تصميم رومانسي فريد: شكل قلب جذاب يضيف لمسة دافئة وراقية على مائدتك. خامات فاخرة: زجاج عالي الجودة يتسم بالشفافية واللمعان مع إطار ذهبي لا يتغير لونه بسهولة. استخدامات متعددة: مثالية لتقديم المكسرات، الشوكولاتة، الحلويات الشرقية، أو كبولات فردية للبودينج والحلي البارد. لمسة ديكورية: بفضل تصميمها المضلع الأنيق، تعتبر قطعة فنية تزين طاولة الضيافة أو ركن القهوة. سهولة العناية: تصميم عملي يسهل استخدامه وتنظيفه، مما يجعله مثالياً للاستخدام اليومي أو المناسبات."', 250, 250, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmkpfse4q0ck401gn3mbr04zj_pole1.webp', 'https://assets.wuiltstore.com/cmkpfsfs80ck601gn3i795qdq_pole2.webp', 'البيت العصري'),
  ('جزامة هوم الوطنية 5 دور بلاستيك مقوى مزودة بعجلات - منظم أحذية عصري وعملي', '"وداعاً للفوضى عند مدخل منزلك مع جزامة هوم من الوطنية للبلاستيك . صُممت هذه الجزامة لتجمع بين المتانة والشكل الجمالي، مما يجعلها الحل الأمثل لتنظيم الأحذية وتوفير المساحة بأسلوب عصري. المواصفات والمميزات: جودة الوطنية المعروفة: مصنوعة من أجود أنواع البلاستيك المقوى الصديق للبيئة لضمان أقصى درجات التحمل. سعة تخزين كبيرة: تتكون من 5 أرفف واسعة، مما يسمح بتنظيم عدد كبير من الأحذية بمختلف مقاساتها. سهولة الحركة: مزودة بـ عجلات متينة تجعل من السهل نقلها وتحريكها أثناء التنظيف أو تغيير مكان الديكور. تصميم ذكي: الأعمدة مصممة بشكل هندسي يوفر ثباتاً فائقاً للجزامة حتى عند امتلائها بالكامل. متوفرة بألوان متعددة: تأتي بتنسيقات ألوان تناسب مختلف أذواق الديكور المنزلي. سهولة التركيب: تصميم بسيط يتيح لك تركيبها في دقائق بدون الحاجة لأدوات معقدة."', 450, 450, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmkpfhdmo0cj401gneyxr94e0_home_g.webp', 'https://assets.wuiltstore.com/cmkpfhf5a0cj601gncsds01m6_home2.webp', 'البيت العصري'),
  ('قلاية هوائية سيلفر كريست 6 لتر ديجيتال 1400 وات - Silver Crest Air Fryer للأكل الصحي', '"استمتعي بأشهى المأكولات المقرمشة بدون تأنيب ضمير مع قلاية سيلفر كريست الهوائية . بفضل سعتها الكبيرة وقوتها الجبارة، ستتمكنين من تحضير وجبات عائلية متكاملة بملعقة زيت واحدة فقط أو بدون زيت تماماً. المواصفات التقنية والمميزات: القوة والأداء: تعمل بمحرك قوي 1400 وات لضمان توزيع حراري مثالي وسرعة في الطهي. سعة عائلية كبيرة: وعاء بحجم 6 لتر يكفي لتحضير كميات كبيرة من الطعام في وقت واحد. تحكم ذكي: شاشة LED ديجيتال تعمل باللمس مع برامج طهي مسبقة (للبطاطس، الدجاج، اللحوم، والأسماك). تصميم فخم: لون أسود مطفي مع تطعيمات ذهبية تضيف لمسة رقي لمطبخك. سهولة التنظيف: وعاء مزود بطبقة غير لاصقة سهلة التنظيف والفك. صحة وتوفير: توفر حتى 80% من الدهون مقارنة بالقلي التقليدي، مما يجعلها مثالية لنمط حياة صحي."', 1199, 1199, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmkpfb9wn0cin01gncvohf0df_615421032_870979269045448_4153525308752763809_n.webp', 'https://assets.wuiltstore.com/cmkpfbbml0cip01gncwzx7vzs_616176215_870979315712110_6871770032509848919_n.webp', 'العروض الحالية'),
  ('شيالة كحك وبسكوت', 'شياله جولد تحفه فنيه شياله ثلاثية بطبق زجاج شيك جدا', 430, 430, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmkpe6v0m0cdx01gncsd4gmci__D8_B4_D9_8A_D8_A7_D9_843.webp', 'https://assets.wuiltstore.com/cmkpe6wux0cdz01gn2gvn7oy7__D8_B4_D9_8A_D8_A7_D9_842.webp', 'البيت العصري'),
  ('مج برطمان زجاج اشكال رمضان', 'تخيل كوباية العناب أو السوبيا الساقعة في "المج" ده مع لمة العيلة بعد التراويح.. 😍 الهدوء والشياكة في تفاصيل الغطاء الخشب والنقوش الذهبية اللي بتخطف العين. 🏮✨ بتحبوا تشربوا إيه أكتر حاجة في رمضان؟ (سوبيا 🥥 ولا قمر دين 🍑؟) قولولنا في الكومنتات! #فرحة_رمضان #تجهيزات_رمضان #هدايا_رمضان #لايف_ستايل #مصر #جمعنا_رمضان', 85, 85, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmkpe1wkn0cdq01gnahmu717n_mug_ramadany.webp', 'https://assets.wuiltstore.com/cmkpe1xd80cdr01gn6kdebjzb_mug_ramadany2.webp', 'العروض الحالية'),
  ('لعبة شطرنج المغناطيس', 'اللعبة الترند شطرنج المغناطيس البورد الكبير 20 مغناطيس', 120, 110, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmjcyfyry04f701irfn0p6o61__D9_85_D8_BA_D9_86_D8_A7.jpg', 'https://assets.wuiltstore.com/cmjcyfy9204f601ir8sns3wnn__D9_85_D8_BA_D9_86_D8_A72.jpg', 'عروض نهاية السنة'),
  ('الشنطه القابلة للطي الجامبو ووتر بروف', 'شنطة سفر خفيفة الوزن مقاومة للماء، مصنوعة من قماش نايلون واوكسفورد خفيف الوزن ومقاوم للماء والتمزق، صلب ومتين وقوي بما فيه الكفاية للحمل، تصلح للعديد من الاستخدامات', 240, 195, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmk76t1st0bwe01fu5a9uf63s_photo_2025-12-30_09-17-33.webp', 'https://assets.wuiltstore.com/cmk76t2ry0bwf01fu01kvcnod_photo_2025-12-30_09-17-34__2_.webp', 'العروض الحالية'),
  ('شنطة فاشون رجالي', 'لو بتدور على شنطة تعيش، تحمي حاجتك، وشكلها يشرفك.. يبقى الفيديو ده ليك. في Perla Space بنقدم لك "الشنطة الدبابة": 🔒 أمان: سوستة بقفل رقمي ضد السرقة. 🌧️ حماية: خامة طاردة للمياه والسوائل. 🔋 تكنولوجيا: اشحن موبايلك من غير ما تفتح الشنطة.', 275, 250, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmk76kqyy0bw901fufeag3v4i_608653498_851779867626282_6370797080883945785_n.webp', 'https://assets.wuiltstore.com/cmk76kq9d0bw801fu9hxn74yx_607970093_913385701233838_6828878138807432266_n.webp', 'العروض الحالية'),
  ('مسدس بابلز', 'مسدس بابلز', 110, 110, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmjddyd4l05xc01ir49c82sd9_photo_2025-12-19_23-16-36.jpg', null, 'العروض الحالية'),
  ('كبسولة حفظ الاعشاب', '✅️ كبسولة حفظ الاعشاب ✅️ اعشاب طازجة ديما ✅️ البقدونس و النعناع فريش ✅️ مده تصل لاسبوعي ✅️ حجم صغير', 65, 65, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmj4812da038m01jxam6uale3__D9_83_D8_A8_D8_B3_D9_88_D9_841.jpg', 'https://assets.wuiltstore.com/cmj4813lc038o01jxc8cbazt5__D9_83_D8_A82.jpg', 'المطبخ العصري'),
  ('Couple ولا.....؟', 'هي لعبة ورقية جماعية تم تصميمها لتكون لعبة اجتماعية، وهي تعتمد على التحديات والتخمينات بين اللاعبين. تتكون اللعبة من 90 بطاقة، يتم توزيعها بين اللاعبين، حيث تحتوي كل بطاقة على سؤال أو تحدي يجب على اللاعب الآخر تخمين الإجابة عليه أو أداء التحدي. يمكن أن تكون الأسئلة المتعلقة بالحياة اليومية، العادات والتقاليد، أو حتى أسئلة أكثر تحديًا تتطلب تفكيرًا عميقًا.', 90, 60, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmbqf7bnt0u7w01lj68ek42xl_51NK0hfEVsL.jpg', 'https://assets.wuiltstore.com/cmbqf7b1m0u7v01ljat9v65qr_download__8_.jpg', 'Card games'),
  ('Fun Tower ( چينچا)', 'بيقولوا الهدم اسهل من البناء ورينا هتعرف تحافظ علي البرج من 60قطعه خشبية اللي هيوقعه هيبقي خسران', 99, 60, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmbqefvhl0u3v01lj33wzd1y2_download__13_.jpg', 'https://assets.wuiltstore.com/cmbqefx5h0u3x01ljh6uc7cmw_download__14_.jpg', 'Card games'),
  ('Identical Cards', '1..2..3 والاسرع فى ملاحظة المتشابه وإعلان ذلك بصوت مرتفع أمام المنافسين يكون الفائز * هى لعبة جماعية من ٢ إل ٦ لاعبين السن : +٣ ولجميع افراد الاسرة ملحوظة في علبه كرتون', 45, 25, 'piece'::public.unit_type, 20, true, 'https://assets.wuiltstore.com/cmbqdsia20u2j01ljgyqyagqp_IMG-20250215-WA0005.jpg', 'https://assets.wuiltstore.com/cmbqdsj120u2k01lj67aq7ggc_485812616_1839570850226847_1420819841849952898_n.jpg', 'Card games'),
  ('اتوبيس كومبليت', 'لو بتدور على لعبة ترجعك لأيام الطفولة، وتضيف جو من المرح والتحدي لكل قعدة، يبقى “أتوبيس كومبليت” هي اختيارك الأول. مناسبة لجميع الأعمار، بتجمع بين سرعة البديهة، والتفكير، والتفاعل الاجتماعي. اطلبها دلوقتي وخلي كل جمعة مليانة ضحك وتنافس.', 99, 60, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmbqeum3h0u4y01lj6et51cjr_494985576_692305673579476_7501039129377903274_n.jpg', 'https://assets.wuiltstore.com/cmbqeulco0u4x01ljhzqacl76_WhatsApp_Image_2025-05-20_at_15.18.37_883aa995.jpg', 'Card games'),
  ('افتح موضوع', 'لعبة “افتح موضوع” مش بس كروت وأفكار… دي مفتاح لعلاقات أعمق، وضحك أكتر، ومواقف عمرها ما هتتنسي. بمجرد ما تبدأ تلعب، هتلاقي إن كل كارت بيقرب الناس من بعض، بيفتح باب جديد للكلام، وبيخلق جو مش ممكن يتكرر. اللعبة دي هي الحل المثالي لكل حد مش بيعرف يبدأ كلام، أو عايز يكسر الروتين، أو نفسه يعيش لحظات اجتماعية حقيقية بعيد عن الشاشات والموبايلات.', 40, 20, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmbqf3k6f0u6001lj41wcezu8__D8_A7_D9_81_D8_AA_D8_AD__D9_85_D9_88_D8_B6_D9_88_D8_B9.webp', 'https://assets.wuiltstore.com/cmbqf3kvr0u6101ljfle38mvo__D8_A7_D9_81_D8_AA_D8_AD__D9_85_D9_88_D8_B6_D9_88_D8_B92.jpg', 'Card games'),
  ('الحريف', 'لو شايف نفسك فاهم كورة… وبتعرف تحلل وتستنتج… لو بتحب السرعة، الضغط، والحسم… لو عايز تثبت لنفسك وصحابك إنك “الحريف الحقيقي”… مناسبه للصغار و الكبار و لكل محبين كرة القدم', 45, 25, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmbqee6lf0u3t01lj498w5th0_download__11_.jpg', 'https://assets.wuiltstore.com/cmbqee49q0u3s01lj4wpygw7n_download__12_.jpg', 'Card games'),
  ('الشفرة', 'فاكر نفسك خبير كورة؟ حافظ كل اللعيبة وتاريخهم وأهدافهم؟ طيب تقدر توصّل اسم لاعب لفريقك من غير ما تقول اسمه ولا ناديه ولا رقمه؟ ولو قلت لك لازم تستخدم كلمة واحدة بس؟ هنا التحدي الحقيقي … مع لعبة الشفره!', 45, 25, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmbqecsd40u3l01lj0rw6eii4__D8_A7_D9_84_D8_B4_D9_81_D8_B1_D8_A9.webp', 'https://assets.wuiltstore.com/cmbqecqbd0u3k01lj9b4ihtls_download__9_.jpg', 'Card games'),
  ('الكلام ع ايه', 'لو نفسك في لعبة خفيفة، مش مكررة، وتناسب كل الناس، فـ اللعبة دي هتكون استثمارك الأفضل في وقتك وضحكتك. اطلبها دلوقتي، وخلي كل قاعدة ليها طعم جديد، وضحكة مختلفة. يبقي ...........الكلام على إيه؟', 49, 25, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmbqeqejj0u4f01ljfc14hb1d_4145htpi9EL._AC_UF1000_1000_QL80_.jpg', 'https://assets.wuiltstore.com/cmbqeqf840u4g01ljh18k5v04_download__7_.jpg', 'Card games'),
  ('بدون كلام', 'يلا نلعب بس بدون كلام افلام ، مسرحيات ، مسلسلات العب وانت مغمض العب وانت واقف علي رجل واحدة 🤦🏻 واحكام تانية كتير جرب دلوقتي بدون كلام ومش هتندم', 49, 25, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmbqe8bbp0u3b01lja6dz8gfs_IMG-20250215-WA0014.jpg', 'https://assets.wuiltstore.com/cmbqe8c1d0u3c01lj3m8h1k76_images.jpg', 'Card games'),
  ('بنك الحظ الاصلي', 'لعبة الزمن الجميل بنك الحظ هتجمع كل الاخوات أو الصحاب ويقضوا أحلى الاوقات لعبة جميع الاجيال والعصور', 70, 57, 'piece'::public.unit_type, 25, true, 'https://assets.wuiltstore.com/cmbqe1q8r0u3001ljfku5h0oo_IMG-20250215-WA0008.jpg', 'https://assets.wuiltstore.com/cmbqe1p7w0u2z01ljh501c6wv_71GORroNkIL.jpg', 'العاب'),
  ('بنك الحظ السعيد', 'هتلعب يعني هتلعب الليدو سلم والثعبان بنك الحظ جمعنالك الالعاب في بوكس واحد يلا بينا', 49, 36, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmbqej9xh0u4401ljb2n48kgz_IMG-20250215-WA0004.jpg', 'https://assets.wuiltstore.com/cmbqejavy0u4501ljdmgf2lun_493110565_692305953579448_8775452901652322543_n.jpg', 'Card games'),
  ('تربو معدن 4 دور مربع', 'تربو معدن 4 دور مربع بعجل متحرك متعدد الاستخدام يستخدم ك تربو للمطبخ للخضار والفاكهه 🥬 أو في الحمام للشاور والشامبو🧻🧴 أو يستخدم في المكتب وغرف الاطفال لحمل جميع الأشياء في مكان واحد مزود بعجل متين لسهوله الحركه والتنظيف خلفه', 615, 615, 'piece'::public.unit_type, 3, true, 'https://assets.wuiltstore.com/cmj4b7v8503er01jxgvpxe009__D8_AA_D8_B1_D8_A8_D9_884.jpg', 'https://assets.wuiltstore.com/cmj4b7u4f03eq01jx01lw6db2__D8_AA_D8_B1_D8_A8_D9_881.jpg', 'المطبخ العصري'),
  ('حقنه تواليت', 'مطهر ومعقم ومطهر 3*1 👌👌 حقنة جيل للحوض والحمام لاصق يدوم طويلا الحقنة الواحدة بتعمل 14 حقنه 🌷 متوفر بروائح متعددة المنتج الأصلي بالكرتونة', 50, 50, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmj4845bf039601jxcb3fc6h9_71DwPl_kCRL._AC_UF350_350_QL80_.jpg', 'https://assets.wuiltstore.com/cmj4846sh039801jx8rr78bdp_589130609_122151052268874034_6729208223350161456_n.jpg', 'الحمام العصري'),
  ('رول استيكر لاصق', 'رول استيكر لاصق ٥ متر × ٦٠ سم غيري شكل رخامة المطبخ والحوائط حراري لاصق مش ورق ضد المايه وضد الحرارة وضد الرطوبة وضد لصق الزيت بيتلزق علي اي حاجه وفي اي مكان حوائط خشب سيراميك ارضيه رخام الوميتال زجاج الخ الالون دهبي وفضي', 70, 70, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmj47cswn037c01jx2w487evo__D8_B1_D9_88_D9_841.jpg', 'https://assets.wuiltstore.com/cmj47cuea037e01jxdz65euik__D8_B1_D9_88_D9_842.jpg', 'Perla Space'),
  ('زاوية حمّام', 'أحدث زاوية حمّام من كرم بلاست 🔥 شكل أنيق + خامة محترمة + باب متحرك ولا أسهل 👌 💧 بتنظم حمّامك 💧 بتدي شكل شيك 💧 وتستحمل شغل السنين', 175, 175, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmj4bam7003ex01jx8ssu27iv__D8_B1_D9_83_D9_863.jpg', 'https://assets.wuiltstore.com/cmj4bao4x03ez01jx3f6g0ict__D8_B1_D9_83_D9_862.jpg', 'الحمام العصري'),
  ('سكرو (Box)', 'لما الحماس يوصل لقمته، والتوتر يخليك على أعصابك في كل كارت… اعرف إنك بتلعب سكرو – النسخة الكاملة! اللعبة دي مش مجرد ورق… دي تجربة كاملة من التفكير، التخطيط، التوقع، والانتصارات المفاجئة. كل كارت فيها ممكن يكون سبب فوزك أو نهايتك، وكل دور هو جولة ذكية ما بين الحظ والقرار الصح.', 99, 50, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmbqfb1wj0u8i01lj188of5wi_IMG-20250310-WA0005.jpg', 'https://assets.wuiltstore.com/cmbqfb3320u8k01ljaqggeg1f_490495606_9754171471313893_2836460690513763418_n.jpg', 'Card games'),
  ('سكوتر اطفال', 'سكوتر اطفال فيه مساعدين وكمان جرس مناسب للاطفال لسن 8 سنوات', 450, 450, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmj489hzr039k01jx13z32lvv__D8_B3_D9_83_D9_88_D8_AA4.jpg', 'https://assets.wuiltstore.com/cmj489im2039l01jx434u2g5j__D8_B3_D9_83_D9_88_D8_AA3.jpg', 'العاب'),
  ('شراب سيليكون', 'شراب سيليكون مبطن', 55, 55, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmj60xsfw01lp01jx9g1eactd__D8_B4_D8_B1_D8_A7_D8_A81.jpg', null, 'البيت العصري'),
  ('طقم قطاعات بالحامل', 'طقم قطاعات بالحامل بلانشة ٤ قطع بلاستيك مضاد للإنزلاق مقاس ٣٠ * ٢٢.٥ سم سميكة كل قطعة لنوع معين (خضروات 🥕/ أسماك 🐟 / لحوم 🍖 / طيور 🐦 ) ومعاها حامل شيك للحفاظ عليها وعشان متخدش حيز بتيجي في علبة شيك', 270, 270, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmj48e214039y01jxebcy8qul__D9_82_D8_B7_D8_A7_D8_B95.jpg', 'https://assets.wuiltstore.com/cmj48e2xr039z01jx09923wjv__D9_82_D8_B7_D8_A7_D8_B94.jpg', 'المطبخ العصري'),
  ('فرشة حمام', 'فرشة حمام بطوط', 40, 40, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmj60rrzv01l701jx8pdt3yu3__D8_A8_D8_B7_D9_88_D8_B7_D8_B6.jpg', null, 'الحمام العصري'),
  ('فووق', 'لعبة “فوووق” هي واحدة من الألعاب القليلة اللي فعلاً تقدر تلعبها أكتر من مرة وتحس إنها مختلفة كل مرة. كل كارت فيها مش بس بيقدم لك سؤال، لكن بيحطك في تحدي جديد بلمسة من الجنون والضحك والإبداع. سواء كنت بتحب المنافسة أو الضحك أو حتى الحوار، هتلاقي في “فوووق” المساحة اللي تخليك تستمتع وتخرج عن الروتين.', 49, 25, 'piece'::public.unit_type, 10, true, 'https://assets.wuiltstore.com/cmbqesy5f0u4u01ljea83d96o_IMG-20250608-WA0028.jpg', null, 'Card games'),
