), resolved_products as (
  select source_products.*, categories.id as category_id
  from source_products
  left join public.categories on categories.name = source_products.category_name
)
insert into public.products (category_id, name, description, price, cost_price, unit_type, stock_quantity, is_available, image_1_url, image_2_url)
select category_id, name, description, price, cost_price, unit_type, stock_quantity, is_available, image_1_url, image_2_url
from resolved_products
where not exists (select 1 from public.products where products.name = resolved_products.name);

notify pgrst, 'reload schema';
